mapper.select:
select id,type,sys_id, sys_name,third_id, third_code, third_name, third_sys_type as sysType
    from third_mapping
where is_deleted=false
and disabled=false
and third_sys_type=#{thirdSysType}
and type=#{type}

select m.sys_id as sysWarehouseId, w.code as thirdWarehouseCode, w.warehouse_id as thirdWarehouseId, w.inventory_sync_mode as inventorySyncMode from third_mapping m left join third_warehouse w on m.third_id = w.warehouse_id and m.type = w.category where m.disabled = false and w.disabled = false and m.third_sys_type = #{sysType} and m.type = 'warehouse' and m.is_deleted = false and w.is_deleted = false
and m.sys_id in
#{warehouseId}
